def _dump(node):
    return ast.dump(node, include_attributes=False)


def _code_shape(code):
    return tuple(getattr(code, name) for name in (
        'co_code', 'co_names', 'co_varnames', 'co_argcount', 'co_posonlyargcount',
        'co_kwonlyargcount', 'co_flags', 'co_freevars', 'co_cellvars')) + (tuple(
            _code_shape(value) if type(value) is CodeType else value for value in code.co_consts),)


def _function(tree, name):
    matches = [node for node in tree.body if type(node) is ast.FunctionDef and node.name == name]
    if len(matches) != 1:
        raise ValueError('one complete original allocation function required: ' + name)
    return matches[0]


def _function_code(code, name):
    matches = [item for item in code.co_consts if type(item) is CodeType
        and item.co_name == name and item.co_qualname == name]
    if len(matches) != 1:
        raise ValueError('one complete allocation code owner required: ' + name)
    return matches[0]


def _changes(role):
    """Closed original call identities; no numeric PC interpreter or callback."""
    if role == 'wait':
        return (("memory.state.progress('scene-sound-byte')",
                 'frame = (yield AllocationSceneWait(memory.state, frame, memory.state.sr).validate())', 1),)
    if role == 'presentation':
        return (('algorithm(memory, frame)', '(yield from algorithm(memory, frame))', 1),
                ('algorithm(memory, entered)', '(yield from algorithm(memory, entered))', 1))
    if role == 'call':
        return (('wait_for_scene_sound_byte_fields(scene, entered)',
                 '(yield from _allocation_wait_view(scene, entered))', 1),
                ('_presentation_call_fields(BattlePresentationMemory(memory.state), frame, continuation, child)',
                 '(yield from _allocation_presentation_view(BattlePresentationMemory(memory.state), frame, continuation, child))', 1))
    if role == 'parent':
        return (('_scene_object_call_fields(memory, frame, 0x83C8, 0x3D7FA)',
                 '(yield from _allocation_object_call_view(memory, frame, 0x83C8, 0x3D7FA))', 1),)
    raise ValueError('one reviewed complete allocation view role required')


def _node(text, statement=False):
    parsed = ast.parse(text).body[0]
    return parsed if statement else parsed.value


def _replace_exact(original, old, new, expected):
    hits = []

    class Replace(ast.NodeTransformer):
        def visit(self, item):
            if isinstance(item, ast.AST) and _dump(item) == _dump(old):
                hits.append(item)
                return ast.copy_location(copy.deepcopy(new), item)
            return super().visit(item)

    changed = Replace().visit(copy.deepcopy(original))
    if len(hits) != expected:
        raise ValueError('exact allocation cooperative site count changed')
    return changed


def _cooperative_tree(tree, role, name):
    """Full original function and module inverse for each private view."""
    original = _function(tree, name)
    if _dump(original) != EXPECTED_OWNERS[role]['AST']:
        raise ValueError('complete reviewed allocation owner differs: ' + role)
    if any(isinstance(item, (ast.Yield, ast.YieldFrom, ast.AsyncFunctionDef)) for item in ast.walk(original)):
        raise ValueError('original allocation source must not already be cooperative')
    lifted = copy.deepcopy(original)
    changes = _changes(role)
    for old, new, expected in changes:
        lifted = _replace_exact(lifted, _node(old, role == 'wait'), _node(new, role == 'wait'), expected)
    inverse = copy.deepcopy(lifted)
    for old, new, expected in reversed(changes):
        inverse = _replace_exact(inverse, _node(new, role == 'wait'), _node(old, role == 'wait'), expected)
    if _dump(inverse) != _dump(original):
        raise ValueError('whole allocation function inverse differs: ' + name)
    changed_tree = copy.deepcopy(tree)
    changed_tree.body[tree.body.index(original)] = lifted
    restored = copy.deepcopy(changed_tree)
    restored.body[tree.body.index(original)] = inverse
    if _dump(restored) != _dump(tree):
        raise ValueError('whole allocation source module inverse differs: ' + role)
    return ast.fix_missing_locations(changed_tree)


def _modules():
    from ..high_level_scene_flows import business_objects
    from ..high_level_gameplay_flow import business_battle, business_services
    from . import business_early_phase, business_late_phase
    return dict(objects=business_objects, battle=business_battle, services=business_services,
        early=business_early_phase, late=business_late_phase)


def _load_exact(module, name, expected_AST, cache):
    original = getattr(module, name)
    if (type(original) is not FunctionType or original.__module__ != module.__name__
            or original.__name__ != name or original.__globals__ is not vars(module)
            or original.__closure__ is not None or original.__code__.co_freevars
            or inspect.isgeneratorfunction(original)):
        raise ValueError('unwrapped complete original allocation owner required: ' + name)
    key = id(module)
    if key not in cache:
        tree = ast.parse(inspect.getsource(module), filename=original.__code__.co_filename)
        plain = compile(tree, original.__code__.co_filename, 'exec', dont_inherit=True)
        cache[key] = (tree, plain)
    tree, plain = cache[key]
    if _dump(_function(tree, name)) != expected_AST:
        raise ValueError('reviewed allocation dependency AST differs: ' + name)
    if _code_shape(_function_code(plain, name)) != _code_shape(original.__code__):
        raise ValueError('loaded complete allocation function differs from its source: ' + name)
    return original, tree


def _admit_phase_dependencies(modules, cache):
    """Only exact full-frame algorithms/routers are admitted; no DTO promotion."""
    for key, expected in EXPECTED_PHASE_DEPENDENCIES.items():
        module_key, name = key.split(':', 1)
        _load_exact(modules[module_key], name, expected, cache)


def _make_views():
    modules = _modules()
    cache = {}
    _admit_phase_dependencies(modules, cache)
    views = {}
    for role in ('wait', 'presentation', 'call', 'parent'):
        spec = EXPECTED_OWNERS[role]
        original, tree = _load_exact(modules[spec['module']], spec['name'], spec['AST'], cache)
        lifted = _cooperative_tree(tree, role, spec['name'])
        code = _function_code(compile(lifted, original.__code__.co_filename,
            'exec', dont_inherit=True), spec['name'])
        namespace = dict(original.__globals__)
        additions = {'AllocationSceneWait': AllocationSceneWait} if role == 'wait' else {}
        if role == 'call':
            additions = dict(_allocation_wait_view=views['wait'],
                _allocation_presentation_view=views['presentation'])
        elif role == 'parent':
            additions = dict(_allocation_object_call_view=views['call'])
        if any(name in namespace for name in additions):
            raise ValueError('private allocation namespace must not replace an original binding')
        namespace.update(additions)
        view = FunctionType(code, namespace, original.__name__, original.__defaults__, None)
        view.__kwdefaults__ = original.__kwdefaults__
        view.__annotations__ = dict(original.__annotations__)
        if not inspect.isgeneratorfunction(view):
            raise ValueError('complete allocation view must preserve its cooperative chain')
        views[role] = view
    return views


def allocation_scene_program(state: SceneState, frame: FirstDeploymentFrame):
    """Yield from the whole original3D654 invocation, without owning outer RTS.

    Other persistent software parents may yield from this function directly.
    It neither enters an IRQ nor supplies a pad, clock, status bit or DATA read.
    """
    state = checked_state(state)
    frame = _movement_frame(state, frame)
    frame.validate(state, True)
    if frame.status != state.sr & 31:
        raise ValueError('actual allocation entry full SR and CCR-X must agree')
    return (yield from _make_views()['parent'](SceneRefreshMemory(state), frame))


@dataclass(frozen=True)
class AllocationSceneWait:
    """Real83CC poll while the caller's3D7FA LONG stays physically active."""
    state: SceneState
    frame: FirstDeploymentFrame
    status_word: int
    poll: int = 0x83CC
    caller_return: int = 0x3D7FA

    @property
    def stage(self):
        return 'original_allocation_scene_frame'

    def validate(self):
        checked_state(self.state)
        _movement_frame(self.state, self.frame)
        self.frame.validate(self.state, True)
        uint(self.status_word, 16)
        if self.poll != 0x83CC or self.caller_return != 0x3D7FA:
            raise ValueError('actual original allocation83CC/3D7FA wait required')
        if self.status_word != self.state.sr or self.frame.status != self.status_word & 31:
            raise ValueError('allocation wait requires actual full SR and CCR-X')
        return self


class PersistentAllocationSceneSession:
    """One3D654 initialization/frame-loop/restart/result lifetime on one Scene."""
    entry_pc = 0x3D654

    def __init__(self, state: SceneState, frame: FirstDeploymentFrame):
        self.state = checked_state(state)
        self.entry = _movement_frame(state, frame)
        self.entry.validate(state, True)
        if frame.status != state.sr & 31:
            raise ValueError('actual allocation entry CCR-X and Scene SR disagree')
        self._thread = threading.get_ident()
        self._program = allocation_scene_program(state, frame)
        self._started = self._complete = self._failed = False
        self.waiting = self.result = None
        self.suspensions = 0

    @property
    def complete(self):
        return self._complete

    @property
    def failed(self):
        return self._failed

    def _same_thread(self):
        if threading.get_ident() != self._thread:
            raise ValueError('one original allocation invocation must stay on its real thread')

    def _take(self, received=None):
        self._same_thread()
        try:
            waiting = next(self._program) if received is None else self._program.send(received)
        except StopIteration as completed:
            self.result = _movement_frame(self.state, completed.value)
            if self.result.stack_cursor.base != self.entry.stack_cursor.base:
                self._failed = True
                raise Boundary('original allocation terminal did not preserve its caller-owned outer SP')
            if self.result.status != self.state.sr & 31:
                self._failed = True
                raise ValueError('original allocation terminal SR and complete frame disagree')
            self._complete, self.waiting = True, None
            return self.result
        except BaseException:
            self._failed = True
            raise
        if type(waiting) is not AllocationSceneWait or waiting.state is not self.state:
            self._failed = True
            raise ValueError('one actual same-Scene allocation wait required')
        try:
            self.waiting = waiting.validate()
        except BaseException:
            self._failed = True
            raise
        self.suspensions += 1
        return self.waiting

    def start(self):
        self._same_thread()
        if self._started:
            raise ValueError('cannot replay original allocation initialization')
        self._started = True
        return self._take()

    def resume(self, returned: FirstDeploymentFrame, pc: int):
        self._same_thread()
        if not self._started or self._failed or self._complete or self.waiting is None:
            raise ValueError('one actual live original allocation suspension required')
        returned = _movement_frame(self.state, returned)
        uint(pc, 32)
        if pc != self.waiting.poll:
            raise MovementContinuationBoundary(pc, returned, 'IRQ did not return to original allocation83CC poll')
        if returned.stack_cursor.base != self.waiting.frame.stack_cursor.base:
            raise Boundary('actual allocation child83C8 return must retain its physical SP')
        if self.state.sr != self.waiting.status_word or returned.status != self.state.sr & 31:
            raise ValueError('allocation IRQ RTE must restore the actual complete SR/CCR-X')
        return self._take(returned)


def run_allocation_scene_blocking_fields(state: SceneState, frame: FirstDeploymentFrame) -> FirstDeploymentFrame:
    """Expose a retained persistent session at an unprovided external IRQ wait."""
    session = PersistentAllocationSceneSession(state, frame)
    returned = session.start()
    if type(returned) is AllocationSceneWait:
        boundary = MovementContinuationBoundary(returned.poll, returned.frame,
            'original allocation scene requires actual external IRQ progress')
        boundary.allocation_scene_session = session
        boundary.allocation_scene_wait = returned
        raise boundary
    return returned
